self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    const urls = PRECACHE.map((p) => new URL(p, self.registration.scope).href);
    const existing = new Set((await cache.keys()).map((r) => r.url));
    let done = 0, failed = 0;
    const total = urls.length;
    const CHUNK = 12;
    for (let i = 0; i < urls.length; i += CHUNK) {
      await Promise.all(urls.slice(i, i + CHUNK).map(async (u) => {
        if (!existing.has(u)) {
          try {
            const res = await fetch(u, { cache: 'no-cache' });
            if (res.ok) await cache.put(u, res); else failed++;
          } catch { failed++; }
        }
        done++;
      }));
      await broadcast({ type: 'progress', done, total, failed });
    }
    await broadcast({ type: 'installed', total, failed });
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== CACHE) await caches.delete(k);
    await self.clients.claim();
    await broadcast({ type: 'ready', version: VERSION });
  })());
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    } catch (e) {
      if (req.mode === 'navigate') {
        const home = await cache.match(new URL('./index.html', self.registration.scope).href);
        if (home) return home;
      }
      throw e;
    }
  })());
});

self.addEventListener('message', async (event) => {
  if (event.data?.type === 'status') {
    const cache = await caches.open(CACHE);
    const keys = await cache.keys();
    event.source?.postMessage({ type: 'status', cached: keys.length, total: PRECACHE.length, version: VERSION });
  }
});

async function broadcast(msg) {
  for (const c of await self.clients.matchAll({ includeUncontrolled: true })) c.postMessage(msg);
}
